```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Low-Poly Goblin</title>

  <style>
    * {
      box-sizing: border-box;
    }

    html,
    body {
      width: 100%;
      height: 100%;
      margin: 0;
      overflow: hidden;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at 50% 35%, #314436 0%, #18231c 48%, #0d130f 100%);
      color: #edf6e7;
    }

    #viewport {
      position: absolute;
      inset: 0;
    }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
    }

    .panel {
      position: absolute;
      top: 20px;
      left: 20px;
      z-index: 10;
      width: min(330px, calc(100vw - 40px));
      padding: 18px 20px;
      border: 1px solid rgba(190, 224, 176, 0.18);
      border-radius: 14px;
      background: rgba(13, 20, 15, 0.72);
      box-shadow: 0 14px 40px rgba(0, 0, 0, 0.28);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      user-select: none;
    }

    h1 {
      margin: 0 0 5px;
      color: #b9e69b;
      font-size: 24px;
      line-height: 1.1;
      letter-spacing: 0.03em;
    }

    p {
      margin: 0;
      color: #a9b9a8;
      font-size: 13px;
      line-height: 1.45;
    }

    .controls {
      position: absolute;
      right: 20px;
      bottom: 20px;
      z-index: 10;
      display: flex;
      flex-wrap: wrap;
      justify-content: flex-end;
      gap: 10px;
    }

    button {
      border: 1px solid rgba(218, 240, 207, 0.22);
      border-radius: 9px;
      padding: 11px 16px;
      background: rgba(20, 31, 23, 0.88);
      color: #e7f2e1;
      font: inherit;
      font-size: 14px;
      font-weight: 650;
      cursor: pointer;
      box-shadow: 0 7px 22px rgba(0, 0, 0, 0.24);
      transition: transform 140ms ease, background 140ms ease, border-color 140ms ease;
    }

    button:hover {
      transform: translateY(-2px);
      border-color: rgba(185, 230, 155, 0.6);
      background: rgba(40, 60, 40, 0.95);
    }

    button:active {
      transform: translateY(0);
    }

    button:disabled {
      opacity: 0.65;
      cursor: wait;
      transform: none;
    }

    #export {
      border-color: #7cab55;
      background: linear-gradient(135deg, #668f42, #3f672d);
      color: white;
    }

    #export:hover {
      background: linear-gradient(135deg, #76a34d, #487534);
    }

    #hint {
      position: absolute;
      left: 20px;
      bottom: 20px;
      z-index: 10;
      color: rgba(219, 234, 211, 0.58);
      font-size: 12px;
      pointer-events: none;
    }

    @media (max-width: 620px) {
      .panel {
        top: 12px;
        left: 12px;
        width: calc(100vw - 24px);
      }

      .controls {
        right: 12px;
        bottom: 12px;
      }

      #hint {
        display: none;
      }
    }
  </style>

  <script type="importmap">
    {
      "imports": {
        "three": "https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js",
        "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.164.1/examples/jsm/"
      }
    }
  </script>
</head>

<body>
  <div id="viewport"></div>

  <section class="panel">
    <h1>Low-Poly Goblin</h1>
    <p>
      A stylized forest goblin with oversized ears, a rusty sword, leather gear,
      and a simple static pose. Ready to export as a self-contained GLB.
    </p>
  </section>

  <div id="hint">Drag to orbit · Scroll to zoom</div>

  <div class="controls">
    <button id="reset">Reset View</button>
    <button id="export">Export GLB</button>
  </div>

  <script type="module">
    import * as THREE from "three";
    import { OrbitControls } from "three/addons/controls/OrbitControls.js";
    import { GLTFExporter } from "three/addons/exporters/GLTFExporter.js";

    const viewport = document.getElementById("viewport");
    const exportButton = document.getElementById("export");
    const resetButton = document.getElementById("reset");

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x18231c);
    scene.fog = new THREE.Fog(0x18231c, 9, 18);

    const camera = new THREE.PerspectiveCamera(
      38,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );
    camera.position.set(6.2, 4.4, 7.4);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.15;
    viewport.appendChild(renderer.domElement);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.target.set(0, 2.1, 0);
    controls.enableDamping = true;
    controls.dampingFactor = 0.07;
    controls.minDistance = 4;
    controls.maxDistance = 13;
    controls.maxPolarAngle = Math.PI * 0.49;

    const hemisphere = new THREE.HemisphereLight(0xb8d8b0, 0x302017, 2.1);
    scene.add(hemisphere);

    const keyLight = new THREE.DirectionalLight(0xfff1ce, 3.2);
    keyLight.position.set(4.5, 8, 5.5);
    keyLight.castShadow = true;
    keyLight.shadow.mapSize.set(2048, 2048);
    keyLight.shadow.camera.left = -5;
    keyLight.shadow.camera.right = 5;
    keyLight.shadow.camera.top = 7;
    keyLight.shadow.camera.bottom = -2;
    keyLight.shadow.camera.near = 0.5;
    keyLight.shadow.camera.far = 20;
    keyLight.shadow.bias = -0.0004;
    scene.add(keyLight);

    const rimLight = new THREE.DirectionalLight(0x8fbcff, 2.4);
    rimLight.position.set(-5, 4, -4);
    scene.add(rimLight);

    const fillLight = new THREE.PointLight(0xb4d781, 12, 10, 2);
    fillLight.position.set(-3, 2.8, 3);
    scene.add(fillLight);

    const material = (color, options = {}) =>
      new THREE.MeshStandardMaterial({
        color,
        roughness: 0.82,
        metalness: 0.02,
        flatShading: true,
        ...options,
      });

    const materials = {
      skin: material(0x668b35),
      skinLight: material(0x7fa044),
      skinDark: material(0x405b25),
      innerEar: material(0x9a6650),
      cloth: material(0x793d28),
      clothDark: material(0x4a271c),
      leather: material(0x3a2419),
      leatherLight: material(0x68422a),
      metal: material(0x6b7375, { metalness: 0.68, roughness: 0.47 }),
      rust: material(0x8c4e32, { metalness: 0.35, roughness: 0.74 }),
      bone: material(0xe4d7a7, { roughness: 0.72 }),
      eye: material(0xf1dc69, { roughness: 0.5 }),
      pupil: material(0x10100d, { roughness: 0.35 }),
      mouth: material(0x251512),
      black: material(0x171713),
      ground: material(0x273329),
    };

    const goblin = new THREE.Group();
    goblin.name = "Goblin";
    scene.add(goblin);

    function addMesh(parent, geometry, mat, name, position = null) {
      const mesh = new THREE.Mesh(geometry, mat);
      mesh.name = name;
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      if (position) mesh.position.set(...position);
      parent.add(mesh);
      return mesh;
    }

    function createLimb(parent, a, b, radiusA, radiusB, name, mat = materials.skin) {
      const start = new THREE.Vector3(...a);
      const end = new THREE.Vector3(...b);
      const direction = end.clone().sub(start);
      const length = direction.length();
      const midpoint = start.clone().add(end).multiplyScalar(0.5);

      const geometry = new THREE.CylinderGeometry(
        radiusB,
        radiusA,
        length,
        6,
        1,
        false
      );

      const mesh = addMesh(parent, geometry, mat, name, midpoint.toArray());
      mesh.quaternion.setFromUnitVectors(
        new THREE.Vector3(0, 1, 0),
        direction.normalize()
      );
      return mesh;
    }

    function createBar(parent, a, b, width, depth, name, mat) {
      const start = new THREE.Vector3(...a);
      const end = new THREE.Vector3(...b);
      const direction = end.clone().sub(start);
      const length = direction.length();
      const midpoint = start.clone().add(end).multiplyScalar(0.5);

      const mesh = addMesh(
        parent,
        new THREE.BoxGeometry(width, length, depth),
        mat,
        name,
        midpoint.toArray()
      );

      mesh.quaternion.setFromUnitVectors(
        new THREE.Vector3(0, 1, 0),
        direction.normalize()
      );
      return mesh;
    }

    // Torso and waist.
    const body = new THREE.Group();
    body.name = "Body";
    goblin.add(body);

    const torso = addMesh(
      body,
      new THREE.IcosahedronGeometry(0.82, 1),
      materials.skin,
      "Torso"
    );
    torso.position.set(0, 1.85, 0);
    torso.scale.set(0.88, 1.03, 0.67);

    const belly = addMesh(
      body,
      new THREE.IcosahedronGeometry(0.69, 1),
      materials.skinLight,
      "Belly"
    );
    belly.position.set(0, 1.55, 0.24);
    belly.scale.set(0.83, 0.82, 0.5);

    const neck = addMesh(
      body,
      new THREE.CylinderGeometry(0.25, 0.31, 0.34, 6),
      materials.skinDark,
      "Neck"
    );
    neck.position.set(0, 2.67, 0);

    const loincloth = addMesh(
      body,
      new THREE.CylinderGeometry(0.54, 0.77, 0.7, 7),
      materials.cloth,
      "Loincloth"
    );
    loincloth.position.set(0, 1.14, 0.01);
    loincloth.rotation.y = Math.PI / 7;

    const belt = addMesh(
      body,
      new THREE.TorusGeometry(0.58, 0.075, 5, 12),
      materials.leather,
      "Belt"
    );
    belt.position.set(0, 1.42, 0);
    belt.rotation.x = Math.PI / 2;

    const buckle = addMesh(
      body,
      new THREE.BoxGeometry(0.2, 0.18, 0.08),
      materials.metal,
      "Belt_Buckle",
      [0, 1.42, 0.54]
    );

    const chestStrap = createBar(
      body,
      [-0.48, 2.38, 0.48],
      [0.43, 1.4, 0.49],
      0.14,
      0.08,
      "Chest_Strap",
      materials.leatherLight
    );
    chestStrap.rotation.z += 0.02;

    const strapBuckle = addMesh(
      body,
      new THREE.BoxGeometry(0.19, 0.19, 0.09),
      materials.metal,
      "Chest_Strap_Buckle",
      [-0.08, 1.83, 0.56]
    );
    strapBuckle.rotation.z = -0.66;

    // Legs, knees, and boots.
    const legs = new THREE.Group();
    legs.name = "Legs";
    goblin.add(legs);

    const legData = [
      { side: -1, name: "Left" },
      { side: 1, name: "Right" },
    ];

    legData.forEach(({ side, name }) => {
      const hip = [side * 0.39, 1.15, 0];
      const knee = [side * 0.48, 0.74, side === 1 ? 0.02 : -0.01];
      const ankle = [side * 0.53, 0.28, side === 1 ? 0.14 : 0.02];

      createLimb(
        legs,
        hip,
        knee,
        0.25,
        0.22,
        `${name}_Thigh`,
        materials.skin
      );

      const kneeMesh = addMesh(
        legs,
        new THREE.IcosahedronGeometry(0.25, 0),
        materials.skinLight,
        `${name}_Knee`,
        knee
      );
      kneeMesh.scale.set(1, 0.9, 1);

      createLimb(
        legs,
        knee,
        ankle,
        0.21,
        0.16,
        `${name}_Calf`,
        materials.skin
      );

      const boot = addMesh(
        legs,
        new THREE.BoxGeometry(0.43, 0.29, 0.7),
        materials.leather,
        `${name}_Boot`,
        [side * 0.53, 0.2, 0.2]
      );
      boot.rotation.y = side * 0.07;

      const bootTop = addMesh(
        legs,
        new THREE.CylinderGeometry(0.21, 0.22, 0.22, 6),
        materials.leatherLight,
        `${name}_Boot_Cuff`,
        [side * 0.52, 0.37, 0.08]
      );

      for (let toe = 0; toe < 3; toe++) {
        addMesh(
          legs,
          new THREE.IcosahedronGeometry(0.11, 0),
          materials.leather,
          `${name}_Toe_${toe + 1}`,
          [
            side * 0.53 + (toe - 1) * 0.12,
            0.13,
            0.54 + Math.abs(toe - 1) * 0.015,
          ]
        );
      }
    });

    // Arms. The right arm is raised to hold the sword.
    const arms = new THREE.Group();
    arms.name = "Arms";
    goblin.add(arms);

    const leftShoulder = [-0.79, 2.34, 0];
    const leftElbow = [-1.16, 1.83, 0.03];
    const leftHand = [-0.78, 1.55, 0.29];

    createLimb(
      arms,
      leftShoulder,
      leftElbow,
      0.25,
      0.19,
      "Left_Upper_Arm"
    );
    createLimb(
      arms,
      leftElbow,
      leftHand,
      0.19,
      0.15,
      "Left_Forearm"
    );

    const leftShoulderPad = addMesh(
      arms,
      new THREE.IcosahedronGeometry(0.34, 0),
      materials.leather,
      "Left_Shoulder_Pad",
      leftShoulder
    );
    leftShoulderPad.scale.set(1.05, 0.65, 1);

    const leftHandMesh = addMesh(
      arms,
      new THREE.IcosahedronGeometry(0.21, 0),
      materials.skinLight,
      "Left_Hand",
      leftHand
    );
    leftHandMesh.scale.set(1.05, 0.85, 0.9);

    for (let finger = 0; finger < 3; finger++) {
      createLimb(
        arms,
        [-0.85 + finger * 0.08, 1.57, 0.41],
        [-0.87 + finger * 0.09, 1.43, 0.5],
        0.055,
        0.045,
        `Left_Finger_${finger + 1}`,
        materials.skin
      );
    }

    const rightShoulder = [0.79, 2.34, 0];
    const rightElbow = [1.17, 2.59, 0.01];
    const rightHand = [1.05, 2.94, 0.08];

    createLimb(
      arms,
      rightShoulder,
      rightElbow,
      0.25,
      0.19,
      "Right_Upper_Arm"
    );
    createLimb(
      arms,
      rightElbow,
      rightHand,
      0.19,
      0.145,
      "Right_Forearm"
    );

    const rightShoulderPad = addMesh(
      arms,
      new THREE.IcosahedronGeometry(0.34, 0),
      materials.leather,
      "Right_Shoulder_Pad",
      rightShoulder
    );
    rightShoulderPad.scale.set(1.05, 0.65, 1);

    const rightHandMesh = addMesh(
      arms,
      new THREE.IcosahedronGeometry(0.2, 0),
      materials.skinLight,
      "Right_Hand",
      rightHand
    );
    rightHandMesh.scale.set(0.95, 1, 0.95);

    // Head and facial features.
    const head = new THREE.Group();
    head.name = "Head";
    head.position.set(0, 3.08, 0);
    head.rotation.z = -0.035;
    goblin.add(head);

    const skull = addMesh(
      head,
      new THREE.IcosahedronGeometry(0.74, 1),
      materials.skin,
      "Skull"
    );
    skull.scale.set(1.02, 0.9, 0.83);

    const jaw = addMesh(
      head,
      new THREE.IcosahedronGeometry(0.56, 0),
      materials.skinLight,
      "Jaw",
      [0, -0.32, 0.13]
    );
    jaw.scale.set(1.05, 0.57, 0.92);

    const browRidge = addMesh(
      head,
      new THREE.BoxGeometry(0.76, 0.13, 0.13),
      materials.skinDark,
      "Brow_Ridge",
      [0, 0.19, 0.57]
    );
    browRidge.rotation.x = -0.08;

    const leftBrow = addMesh(
      head,
      new THREE.BoxGeometry(0.34, 0.09, 0.1),
      materials.skinDark,
      "Left_Eyebrow",
      [-0.23, 0.3, 0.62]
    );
    leftBrow.rotation.z = -0.13;

    const rightBrow = addMesh(
      head,
      new THREE.BoxGeometry(0.34, 0.09, 0.1),
      materials.skinDark,
      "Right_Eyebrow",
      [0.23, 0.3, 0.62]
    );
    rightBrow.rotation.z = 0.13;

    [-1, 1].forEach((side, index) => {
      const label = side < 0 ? "Left" : "Right";

      addMesh(
        head,
        new THREE.IcosahedronGeometry(0.145, 1),
        materials.eye,
        `${label}_Eye`,
        [side * 0.23, 0.11, 0.615]
      );

      const pupil = addMesh(
        head,
        new THREE.IcosahedronGeometry(0.07, 0),
        materials.pupil,
        `${label}_Pupil`,
        [side * 0.23, 0.11, 0.735]
      );
      pupil.scale.set(0.8, 1.12, 0.55);

      addMesh(
        head,
        new THREE.ConeGeometry(0.085, 0.29, 5),
        materials.bone,
        `${label}_Tusk`,
        [side * 0.28, -0.28, 0.66]
      );
    });

    const nose = addMesh(
      head,
      new THREE.ConeGeometry(0.2, 0.52, 4),
      materials.skinLight,
      "Nose",
      [0, -0.05, 0.72]
    );
    nose.rotation.x = Math.PI / 2;
    nose.rotation.z = Math.PI / 4;
    nose.scale.set(1, 1, 0.78);

    const mouth = addMesh(
      head,
      new THREE.BoxGeometry(0.48, 0.085, 0.07),
      materials.mouth,
      "Mouth",
      [0, -0.37, 0.58]
    );
    mouth.rotation.x = -0.07;

    // Large pointed ears.
    const leftEar = addMesh(
      head,
      new THREE.ConeGeometry(0.39, 1.05, 3),
      materials.skin,
      "Left_Ear",
      [-0.83, 0.02, -0.02]
    );
    leftEar.rotation.z = Math.PI / 2 + 0.08;
    leftEar.rotation.y = -0.12;
    leftEar.scale.set(1, 1, 0.82);

    const rightEar = addMesh(
      head,
      new THREE.ConeGeometry(0.39, 1.05, 3),
      materials.skin,
      "Right_Ear",
      [0.83, 0.02, -0.02]
    );
    rightEar.rotation.z = -Math.PI / 2 - 0.08;
    rightEar.rotation.y = 0.12;
    rightEar.scale.set(1, 1, 0.82);

    const leftInnerEar = addMesh(
      head,
      new THREE.ConeGeometry(0.21, 0.67, 3),
      materials.innerEar,
      "Left_Inner_Ear",
      [-0.83, 0.03, 0.16]
    );
    leftInnerEar.rotation.z = Math.PI / 2 + 0.08;
    leftInnerEar.rotation.y = -0.12;
    leftInnerEar.scale.set(1, 1, 0.5);

    const rightInnerEar = addMesh(
      head,
      new THREE.ConeGeometry(0.21, 0.67, 3),
      materials.innerEar,
      "Right_Inner_Ear",
      [0.83, 0.03, 0.16]
    );
    rightInnerEar.rotation.z = -Math.PI / 2 - 0.08;
    rightInnerEar.rotation.y = 0.12;
    rightInnerEar.scale.set(1, 1, 0.5);

    // A simple rusty sword.
    const sword = new THREE.Group();
    sword.name = "Rusty_Sword";
    sword.position.set(1.05, 2.82, 0.1);
    sword.rotation.z = -0.16;
    sword.rotation.y = -0.08;
    goblin.add(sword);

    const bladeShape = new THREE.Shape();
    bladeShape.moveTo(-0.14, 0.12);
    bladeShape.lineTo(0.14, 0.12);
    bladeShape.lineTo(0.18, 1.13);
    bladeShape.lineTo(0, 1.48);
    bladeShape.lineTo(-0.18, 1.13);
    bladeShape.closePath();

    const bladeGeometry = new THREE.ExtrudeGeometry(bladeShape, {
      depth: 0.09,
      bevelEnabled: false,
      curveSegments: 1,
    });
    bladeGeometry.translate(0, 0, -0.045);

    const blade = addMesh(
      sword,
      bladeGeometry,
      materials.metal,
      "Blade"
    );

    const bladeEdge = addMesh(
      sword,
      new THREE.BoxGeometry(0.035, 0.88, 0.105),
      materials.rust,
      "Blade_Edge",
      [0, 0.64, 0]
    );

    const crossguard = addMesh(
      sword,
      new THREE.BoxGeometry(0.78, 0.13, 0.16),
      materials.rust,
      "Crossguard",
      [0, 0.04, 0]
    );
    crossguard.rotation.z = -0.03;

    const grip = addMesh(
      sword,
      new THREE.CylinderGeometry(0.075, 0.085, 0.43, 7),
      materials.leather,
      "Grip",
      [0, -0.25, 0]
    );

    const pommel = addMesh(
      sword,
      new THREE.IcosahedronGeometry(0.13, 0),
      materials.rust,
      "Pommel",
      [0, -0.5, 0]
    );
    pommel.scale.set(1, 0.8, 0.8);

    // A small bone charm attached to the belt.
    const charm = new THREE.Group();
    charm.name = "Bone_Charm";
    charm.position.set(-0.49, 1.16, 0.3);
    charm.rotation.z = 0.25;
    goblin.add(charm);

    addMesh(
      charm,
      new THREE.CylinderGeometry(0.07, 0.09, 0.42, 5),
      materials.bone,
      "Charm_Shaft",
      [0, 0, 0]
    );

    const charmTip = addMesh(
      charm,
      new THREE.ConeGeometry(0.09, 0.18, 5),
      materials.bone,
      "Charm_Tip",
      [0, 0.28, 0]
    );

    // Display-only ground; it is intentionally not part of the GLB export.
    const ground = new THREE.Mesh(
      new THREE.CircleGeometry(5.5, 48),
      materials.ground
    );
    ground.name = "Display_Ground";
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = 0.015;
    ground.receiveShadow = true;
    scene.add(ground);

    const pedestal = new THREE.Mesh(
      new THREE.CylinderGeometry(2.05, 2.25, 0.14, 32),
      material(0x1b271e, { roughness: 0.95 })
    );
    pedestal.name = "Display_Pedestal";
    pedestal.position.y = -0.065;
    pedestal.receiveShadow = true;
    scene.add(pedestal);

    const ring = new THREE.Mesh(
      new THREE.TorusGeometry(2.02, 0.025, 4, 64),
      new THREE.MeshBasicMaterial({ color: 0x62834d })
    );
    ring.rotation.x = Math.PI / 2;
    ring.position.y = 0.012;
    scene.add(ring);

    function resetView() {
      camera.position.set(6.2, 4.4, 7.4);
      controls.target.set(0, 2.1, 0);
      controls.update();
    }

    resetButton.addEventListener("click", resetView);

    exportButton.addEventListener("click", async () => {
      exportButton.disabled = true;
      const previousText = exportButton.textContent;
      exportButton.textContent = "Exporting…";

      try {
        const exporter = new GLTFExporter();
        const result = await exporter.parseAsync(goblin, {
          binary: true,
          onlyVisible: true,
          trs: false,
          maxTextureSize: 2048,
        });

        const blob = new Blob([result], { type: "model/gltf-binary" });
        const url = URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.href = url;
        link.download = "low-poly-goblin.glb";
        document.body.appendChild(link);
        link.click();
        link.remove();

        setTimeout(() => URL.revokeObjectURL(url), 1500);
        exportButton.textContent = "Exported!";
      } catch (error) {
        console.error(error);
        exportButton.textContent = "Export Failed";
      } finally {
        setTimeout(() => {
          exportButton.disabled = false;
          exportButton.textContent = previousText;
        }, 1600);
      }
    });

    function resize() {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    }

    window.addEventListener("resize", resize);

    renderer.setAnimationLoop(() => {
      controls.update();
      renderer.render(scene, camera);
    });
  </script>
</body>
</html>
```

Save the following as **`dragon-boss.html`** and open it in a modern browser. It generates a textured, low-poly dragon boss with wings, horns, armor, a rocky pedestal, and two exported animations: **Idle_Breath** and **Roar_Attack**.

The **Export GLB** button downloads a binary GLB suitable for importing into Godot. The HTML uses Three.js from a CDN, so an internet connection is required.

