  <script type="module">
    import * as THREE from "three";
    import { GLTFExporter } from "three/addons/exporters/GLTFExporter.js";
    import { OrbitControls } from "three/addons/controls/OrbitControls.js";

    // -------------------------------------------------------------------------
    // Renderer and scene
    // -------------------------------------------------------------------------

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      alpha: true,
      powerPreference: "high-performance"
    });

    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.16;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.domElement.setAttribute(
      "aria-label",
      "Interactive 3D preview of a low-poly fox companion"
    );
    document.body.prepend(renderer.domElement);

    const scene = new THREE.Scene();

    const camera = new THREE.PerspectiveCamera(
      35,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );
    camera.position.set(4.7, 3.05, 6.4);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.target.set(0, 1.02, -0.15);
    controls.enableDamping = true;
    controls.dampingFactor = 0.055;
    controls.minDistance = 3.5;
    controls.maxDistance = 11;
    controls.minPolarAngle = 0.25;
    controls.maxPolarAngle = Math.PI * 0.49;

    const hemisphere = new THREE.HemisphereLight(
      0xcfe7ec,
      0x26332e,
      2.15
    );
    scene.add(hemisphere);

    const keyLight = new THREE.DirectionalLight(0xffe0b8, 3.6);
    keyLight.position.set(4.5, 7, 4.5);
    keyLight.castShadow = true;
    keyLight.shadow.mapSize.set(2048, 2048);
    keyLight.shadow.camera.left = -5;
    keyLight.shadow.camera.right = 5;
    keyLight.shadow.camera.top = 5;
    keyLight.shadow.camera.bottom = -5;
    keyLight.shadow.camera.near = 0.5;
    keyLight.shadow.camera.far = 20;
    keyLight.shadow.normalBias = 0.025;
    scene.add(keyLight);

    const rimLight = new THREE.DirectionalLight(0x8ed9e2, 2.1);
    rimLight.position.set(-5, 4, -5);
    scene.add(rimLight);

    const fillLight = new THREE.PointLight(0xffc47c, 1.1, 12);
    fillLight.position.set(-3, 2.5, 3);
    scene.add(fillLight);

    // Preview-only ground, excluded from the exported GLB.
    const ground = new THREE.Mesh(
      new THREE.CircleGeometry(4.5, 48),
      new THREE.MeshStandardMaterial({
        color: 0x172c30,
        roughness: 0.96,
        metalness: 0,
        transparent: true,
        opacity: 0.88
      })
    );
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.025;
    ground.receiveShadow = true;
    scene.add(ground);

    // -------------------------------------------------------------------------
    // Materials
    // -------------------------------------------------------------------------

    const materials = {
      fur: new THREE.MeshStandardMaterial({
        color: 0xd9682f,
        roughness: 0.9,
        metalness: 0,
        flatShading: true
      }),
      furLight: new THREE.MeshStandardMaterial({
        color: 0xe98942,
        roughness: 0.88,
        metalness: 0,
        flatShading: true
      }),
      cream: new THREE.MeshStandardMaterial({
        color: 0xf3dfbd,
        roughness: 0.96,
        metalness: 0,
        flatShading: true
      }),
      dark: new THREE.MeshStandardMaterial({
        color: 0x25262a,
        roughness: 0.83,
        metalness: 0.02,
        flatShading: true
      }),
      innerEar: new THREE.MeshStandardMaterial({
        color: 0x63312f,
        roughness: 0.95,
        metalness: 0,
        flatShading: true
      }),
      nose: new THREE.MeshStandardMaterial({
        color: 0x171a20,
        roughness: 0.58,
        metalness: 0.04,
        flatShading: true
      }),
      collar: new THREE.MeshStandardMaterial({
        color: 0x277d83,
        roughness: 0.73,
        metalness: 0.05,
        flatShading: true
      }),
      tag: new THREE.MeshStandardMaterial({
        color: 0xe5b459,
        roughness: 0.38,
        metalness: 0.55,
        flatShading: true
      }),
      eyeGlint: new THREE.MeshBasicMaterial({
        color: 0xffffff
      })
    };

    // Shared low-poly geometry.
    const icoGeometry = new THREE.IcosahedronGeometry(1, 1);
    const simpleIcoGeometry = new THREE.IcosahedronGeometry(1, 0);

    // -------------------------------------------------------------------------
    // Geometry helpers
    // -------------------------------------------------------------------------

    function makeMesh(
      geometry,
      material,
      name,
      parent,
      position = [0, 0, 0],
      scale = [1, 1, 1]
    ) {
      const mesh = new THREE.Mesh(geometry, material);
      mesh.name = name;
      mesh.position.set(...position);
      mesh.scale.set(...scale);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function ellipsoid(
      name,
      parent,
      material,
      position,
      scale,
      simple = false
    ) {
      return makeMesh(
        simple ? simpleIcoGeometry : icoGeometry,
        material,
        name,
        parent,
        position,
        scale
      );
    }

    function makeGroup(name, parent, position = [0, 0, 0]) {
      const group = new THREE.Group();
      group.name = name;
      group.position.set(...position);
      parent.add(group);
      return group;
    }

    // -------------------------------------------------------------------------
    // Fox model
    // -------------------------------------------------------------------------

    const fox = makeGroup("FoxCompanion", scene);

    // Torso and haunches.
    const torso = ellipsoid(
      "Torso",
      fox,
      materials.fur,
      [0, 0.84, -0.12],
      [0.62, 0.58, 0.93]
    );

    ellipsoid(
      "UpperChest",
      fox,
      materials.furLight,
      [0, 1.05, 0.44],
      [0.43, 0.43, 0.34]
    );

    ellipsoid(
      "ChestBib",
      fox,
      materials.cream,
      [0, 0.73, 0.61],
      [0.43, 0.49, 0.32]
    );

    ellipsoid(
      "HaunchLeft",
      fox,
      materials.fur,
      [-0.4, 0.66, -0.46],
      [0.32, 0.42, 0.47]
    );

    ellipsoid(
      "HaunchRight",
      fox,
      materials.fur,
      [0.4, 0.66, -0.46],
      [0.32, 0.42, 0.47]
    );

    ellipsoid(
      "Neck",
      fox,
      materials.furLight,
      [0, 1.28, 0.45],
      [0.39, 0.35, 0.35]
    );

    // Collar and tag.
    const collar = makeMesh(
      new THREE.TorusGeometry(0.405, 0.065, 5, 12),
      materials.collar,
      "Collar",
      fox,
      [0, 1.31, 0.53]
    );

    makeMesh(
      simpleIcoGeometry,
      materials.tag,
      "CollarTag",
      fox,
      [0, 1.22, 0.61],
      [0.11, 0.14, 0.055]
    );

    // Head assembly. The fox faces toward positive Z.
    const headPivot = makeGroup("HeadPivot", fox, [0, 1.31, 0.49]);

    ellipsoid(
      "Head",
      headPivot,
      materials.fur,
      [0, 0.27, 0.13],
      [0.56, 0.49, 0.51]
    );

    ellipsoid(
      "Muzzle",
      headPivot,
      materials.cream,
      [0, 0.11, 0.55],
      [0.34, 0.235, 0.36]
    );

    ellipsoid(
      "CheekLeft",
      headPivot,
      materials.cream,
      [-0.34, 0.1, 0.25],
      [0.22, 0.22, 0.24]
    );

    ellipsoid(
      "CheekRight",
      headPivot,
      materials.cream,
      [0.34, 0.1, 0.25],
      [0.22, 0.22, 0.24]
    );

    // Small cheek tufts add a readable low-poly silhouette.
    const leftTuft = makeMesh(
      new THREE.ConeGeometry(0.15, 0.35, 3),
      materials.fur,
      "CheekTuftLeft",
      headPivot,
      [-0.48, 0.1, 0.23]
    );
    leftTuft.rotation.z = -Math.PI / 2;

    const rightTuft = makeMesh(
      new THREE.ConeGeometry(0.15, 0.35, 3),
      materials.fur,
      "CheekTuftRight",
      headPivot,
      [0.48, 0.1, 0.23]
    );
    rightTuft.rotation.z = Math.PI / 2;

    // Nose and little mouth marks.
    ellipsoid(
      "Nose",
      headPivot,
      materials.nose,
      [0, 0.19, 0.865],
      [0.145, 0.095, 0.085],
      true
    );

    const mouthLeft = makeMesh(
      new THREE.BoxGeometry(0.09, 0.023, 0.022),
      materials.nose,
      "MouthLeft",
      headPivot,
      [-0.07, 0.035, 0.845]
    );
    mouthLeft.rotation.z = -0.22;

    const mouthRight = makeMesh(
      new THREE.BoxGeometry(0.09, 0.023, 0.022),
      materials.nose,
      "MouthRight",
      headPivot,
      [0.07, 0.035, 0.845]
    );
    mouthRight.rotation.z = 0.22;

    // Eyes are groups so they can blink by scaling vertically.
    function makeEye(name, x) {
      const eye = makeGroup(name, headPivot, [x, 0.39, 0.48]);

      ellipsoid(
        `${name}Ball`,
        eye,
        materials.nose,
        [0, 0, 0],
        [0.105, 0.13, 0.075],
        true
      );

      makeMesh(
        simpleIcoGeometry,
        materials.eyeGlint,
        `${name}Glint`,
        eye,
        [0.033, 0.048, 0.067],
        [0.026, 0.031, 0.018]
      );

      return eye;
    }

    const eyeLeft = makeEye("EyeLeft", -0.235);
    const eyeRight = makeEye("EyeRight", 0.235);

    // Ears.
    function makeEar(name, x, splay) {
      const ear = makeGroup(name, headPivot, [x, 0.61, 0.0]);
      ear.rotation.z = splay;

      makeMesh(
        new THREE.ConeGeometry(0.29, 0.61, 3, 1),
        materials.fur,
        `${name}Outer`,
        ear,
        [0, 0.265, 0],
        [1, 1, 0.86]
      );

      makeMesh(
        new THREE.ConeGeometry(0.19, 0.43, 3, 1),
        materials.innerEar,
        `${name}Inner`,
        ear,
        [0, 0.27, 0.115],
        [0.72, 0.74, 0.42]
      );

      return ear;
    }

    const earLeft = makeEar("EarLeft", -0.34, 0.13);
    const earRight = makeEar("EarRight", 0.34, -0.13);

    // Legs.
    function makeLeg(name, x, z, rear = false) {
      const pivot = makeGroup(name, fox, [x, rear ? 0.64 : 0.68, z]);

      ellipsoid(
        `${name}Upper`,
        pivot,
        materials.fur,
        [0, -0.19, 0],
        rear ? [0.205, 0.36, 0.245] : [0.155, 0.35, 0.17]
      );

      ellipsoid(
        `${name}Lower`,
        pivot,
        materials.furLight,
        [0, -0.43, rear ? -0.01 : 0.025],
        rear ? [0.14, 0.22, 0.16] : [0.12, 0.22, 0.13]
      );

      ellipsoid(
        `${name}Paw`,
        pivot,
        materials.dark,
        [0, -0.545, rear ? -0.035 : 0.085],
        rear ? [0.205, 0.145, 0.255] : [0.175, 0.14, 0.235],
        true
      );

      return pivot;
    }

    const legFrontLeft = makeLeg("LegFrontLeft", -0.285, 0.48);
    const legFrontRight = makeLeg("LegFrontRight", 0.285, 0.48);
    const legRearLeft = makeLeg("LegRearLeft", -0.405, -0.37, true);
    const legRearRight = makeLeg("LegRearRight", 0.405, -0.37, true);

    // Three-part animated tail.
    const tailBase = makeGroup("TailBase", fox, [0, 0.79, -0.82]);
    tailBase.rotation.x = 0.28;

    ellipsoid(
      "TailBaseFur",
      tailBase,
      materials.fur,
      [0, 0, -0.38],
      [0.35, 0.35, 0.58]
    );

    const tailMid = makeGroup("TailMid", tailBase, [0, 0, -0.93]);
    tailMid.rotation.x = 0.12;

    ellipsoid(
      "TailMidFur",
      tailMid,
      materials.furLight,
      [0, 0, -0.37],
      [0.28, 0.28, 0.53]
    );

    const tailTip = makeGroup("TailTip", tailMid, [0, 0, -0.84]);

    ellipsoid(
      "TailCreamTip",
      tailTip,
      materials.cream,
      [0, 0, -0.36],
      [0.235, 0.235, 0.49]
    );

    // -------------------------------------------------------------------------
    // Idle animation
    // -------------------------------------------------------------------------

    function quaternionValues(eulerList) {
      const values = [];

      for (const euler of eulerList) {
        const q = new THREE.Quaternion().setFromEuler(
          new THREE.Euler(euler[0], euler[1], euler[2])
        );
        values.push(q.x, q.y, q.z, q.w);
      }

      return values;
    }

    function quaternionTrack(name, times, eulerList) {
      return new THREE.QuaternionKeyframeTrack(
        name,
        times,
        quaternionValues(eulerList)
      );
    }

    const idleTimes = [0, 1, 2, 3, 4];

    const tracks = [
      new THREE.VectorKeyframeTrack(
        "FoxCompanion.position",
        [0, 1, 2, 3, 4],
        [
          0, 0, 0,
          0, 0.025, 0,
          0, 0.012, 0,
          0, 0.035, 0,
          0, 0, 0
        ]
      ),

      quaternionTrack(
        "FoxCompanion.quaternion",
        idleTimes,
        [
          [0, 0, 0],
          [0, 0.025, 0.012],
          [0, 0, 0],
          [0, -0.025, -0.012],
          [0, 0, 0]
        ]
      ),

      quaternionTrack(
        "HeadPivot.quaternion",
        idleTimes,
        [
          [0.03, 0, 0],
          [0.045, -0.065, 0.018],
          [0.035, 0.055, -0.018],
          [0.04, -0.035, 0.012],
          [0.03, 0, 0]
        ]
      ),

      quaternionTrack(
        "EarLeft.quaternion",
        idleTimes,
        [
          [0, 0, 0.13],
          [0, 0, 0.08],
          [-0.06, 0, 0.19],
          [0.02, 0, 0.13],
          [0, 0, 0.13]
        ]
      ),

      quaternionTrack(
        "EarRight.quaternion",
        idleTimes,
        [
          [0, 0, -0.13],
          [0, 0, -0.16],
          [0.04, 0, -0.09],
          [-0.025, 0, -0.14],
          [0, 0, -0.13]
        ]
      ),

      quaternionTrack(
        "TailBase.quaternion",
        idleTimes,
        [
          [0.28, 0, -0.02],
          [0.38, 0.06, 0.13],
          [0.31, -0.03, -0.08],
          [0.39, 0.04, 0.11],
          [0.28, 0, -0.02]
        ]
      ),

      quaternionTrack(
        "TailMid.quaternion",
        idleTimes,
        [
          [0.12, 0, 0.02],
          [0.03, 0.04, -0.08],
          [0.16, -0.04, 0.09],
          [0.05, 0.025, -0.07],
          [0.12, 0, 0.02]
        ]
      ),

      quaternionTrack(
        "LegFrontLeft.quaternion",
        idleTimes,
        [
          [0, 0, 0],
          [0.025, 0, 0],
          [0, 0, 0],
          [-0.02, 0, 0],
          [0, 0, 0]
        ]
      ),

      quaternionTrack(
        "LegFrontRight.quaternion",
        idleTimes,
        [
          [0, 0, 0],
          [-0.025, 0, 0],
          [0, 0, 0],
          [0.02, 0, 0],
          [0, 0, 0]
        ]
      ),

      new THREE.VectorKeyframeTrack(
        "Torso.scale",
        [0, 2, 4],
        [
          0.62, 0.58, 0.93,
          0.62, 0.607, 0.93,
          0.62, 0.58, 0.93
        ]
      ),

      new THREE.VectorKeyframeTrack(
        "EyeLeft.scale",
        [0, 2.2, 2.34, 2.52, 4],
        [
          1, 1, 1,
          1, 1, 1,
          1, 0.08, 1,
          1, 1, 1,
          1, 1, 1
        ]
      ),

      new THREE.VectorKeyframeTrack(
        "EyeRight.scale",
        [0, 2.2, 2.34, 2.52, 4],
        [
          1, 1, 1,
          1, 1, 1,
          1, 0.08, 1,
          1, 1, 1,
          1, 1, 1
        ]
      )
    ];

    const idleClip = new THREE.AnimationClip("Idle", 4, tracks);

    const mixer = new THREE.AnimationMixer(fox);
    const idleAction = mixer.clipAction(idleClip);
    idleAction.setLoop(THREE.LoopRepeat, Infinity);
    idleAction.play();

    // -------------------------------------------------------------------------
    // Export controls
    // -------------------------------------------------------------------------

    const exportButton = document.getElementById("exportButton");
    const pauseButton = document.getElementById("pauseButton");
    const status = document.getElementById("status");

    let paused = false;

    pauseButton.addEventListener("click", () => {
      paused = !paused;
      idleAction.paused = paused;
      pauseButton.textContent = paused ? "Play" : "Pause";
    });

    exportButton.addEventListener("click", async () => {
      exportButton.disabled = true;
      status.textContent = "Building animated GLB…";

      try {
        // Ensure all animated node transforms are current before export.
        mixer.update(0);
        fox.updateMatrixWorld(true);

        const exporter = new GLTFExporter();
        const result = await exporter.parseAsync(fox, {
          binary: true,
          animations: [idleClip],
          onlyVisible: true,
          truncateDrawRange: true
        });

        const blob = new Blob([result], {
          type: "model/gltf-binary"
        });

        const url = URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.href = url;
        link.download = "fox-companion.glb";
        document.body.appendChild(link);
        link.click();
        link.remove();

        setTimeout(() => URL.revokeObjectURL(url), 1500);

        status.textContent =
          "fox-companion.glb exported with the Idle animation.";
      } catch (error) {
        console.error(error);
        status.textContent = "Export failed. Check the browser console.";
      } finally {
        exportButton.disabled = false;
      }
    });

    // -------------------------------------------------------------------------
    // Render loop and resizing
    // -------------------------------------------------------------------------

    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const delta = Math.min(clock.getDelta(), 0.05);
      mixer.update(delta);

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();

      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.setSize(window.innerWidth, window.innerHeight);
    });
  </script>
</body>
</html>
